    return new HttpShipmentService(factory.CreateClient("ShipmentTracker.ServerAPI"));
});

await builder.Build().RunAsync();
```

Wait — in Blazor WebAssembly, cookies are automatically sent with `HttpClient` requests when the base address matches. We don't need a CookieHandler. Let me simplify:

```csharp
using Microsoft.AspNetCore.Components.WebAssembly.Hosting;
using ShipmentTracker.Client.Services;

var builder = WebAssemblyHostBuilder.CreateDefault(args);

builder.Services.AddAuthorizationCore();
builder.Services.AddCascadingAuthenticationState();
builder.Services.AddAuthenticationStateDeserialization();

builder.Services.AddScoped(sp =>
    new HttpClient { BaseAddress = new Uri(builder.HostEnvironment.BaseAddress) });
builder.Services.AddScoped<IShipmentService, HttpShipmentService>();

await builder.Build().RunAsync();
```

