                            <td>@s.RecipientName</td>
                            <td><span class="badge @GetStatusBadgeClass(s.Status)">@s.Status</span></td>
                            <td>@(s.EstimatedDelivery?.ToString("MMM dd, yyyy") ?? "TBD")</td>
                            <td>
                                @if (s.Status != ShipmentStatus.Delivered && s.Status != ShipmentStatus.Cancelled)
                                {
                                    <div class="btn-group btn-group-sm">
                                        @if (s.Status == ShipmentStatus.Pending)
                                        {
                                            <button class="btn btn-outline-info" @onclick="() => UpdateStatus(s, ShipmentStatus.PickedUp)"
                                                    disabled="@updatingId.HasValue">Pick Up</button>
                                        }
                                        @if (s.Status == ShipmentStatus.PickedUp)
                                        {
                                            <button class="btn btn-outline-primary" @onclick="() => UpdateStatus(s, ShipmentStatus.InTransit)"
                                                    disabled="@updatingId.HasValue">In Transit</button>
                                        }
                                        @if (s.Status == ShipmentStatus.InTransit)
                                        {
                                            <button class="btn btn-outline-warning" @onclick="() => UpdateStatus(s, ShipmentStatus.OutForDelivery)"
                                                    disabled="@updatingId.HasValue">Out for Delivery</button>
                                        }
                                        @if (s.Status == ShipmentStatus.OutForDelivery)
                                        {
                                            <button class="btn btn-outline-success" @onclick="() => UpdateStatus(s, ShipmentStatus.Delivered)"
                                                    disabled="@updatingId.HasValue">Deliver</button>
                                        }
                                        <button class="btn btn-outline-danger" @onclick="() => UpdateStatus(s, ShipmentStatus.Cancelled)"
                                                disabled="@updatingId.HasValue">Cancel</button>
                                    </div>
                                }
                                else
                                {
                                    <span class="text-muted">—</span>
                                }
                            </td>
                        </tr>
                    }
                </tbody>
            </table>
        </div>
    }
</div>

@code {
    private List<ShipmentDto>? shipments;
    private string? searchTerm;
    private string? statusFilter;
    private bool isLoading;
    private int? updatingId;
    private string? errorMessage;

    protected override async Task OnInitializedAsync()
    {
        await LoadShipments();
    }

    private void HandleSearchKeyDown(KeyboardEventArgs e)
    {
        if (e.Key == "Enter") _ = LoadShipments();
    }

    private async Task LoadShipments()
    {
        isLoading = true;
        errorMessage = null;
        try
        {
            shipments = await ShipmentService.GetShipmentsAsync(statusFilter, searchTerm);
        }
        catch (Exception ex)
        {
            errorMessage = $"Failed to load shipments: {ex.Message}";
        }
        finally
        {
            isLoading = false;
        }
    }

    private async Task UpdateStatus(ShipmentDto shipment, ShipmentStatus newStatus)
    {
        updatingId = shipment.Id;
        errorMessage = null;
        try
        {
            var updated = await ShipmentService.UpdateShipmentStatusAsync(shipment.Id, newStatus);
            var index = shipments!.FindIndex(s => s.Id == updated.Id);
            if (index >= 0) shipments[index] = updated;
        }
        catch (Exception ex)
        {
            errorMessage = $"Failed to update status: {ex.Message}";
        }
        finally
        {
            updatingId = null;
        }
    }

    private static string GetStatusBadgeClass(ShipmentStatus status) => status switch
    {
        ShipmentStatus.Pending => "bg-secondary",
        ShipmentStatus.PickedUp => "bg-info",
        ShipmentStatus.InTransit => "bg-primary",
        ShipmentStatus.OutForDelivery => "bg-warning text-dark",
        ShipmentStatus.Delivered => "bg-success",
        ShipmentStatus.Cancelled => "bg-danger",
        _ => "bg-secondary"
    };
}
```

