                {
                    <option value="@s">@s</option>
                }
            </select>
        </div>
        <div class="col-md-2">
            <button class="btn btn-primary w-100" @onclick="LoadShipments" disabled="@isLoading">
                @if (isLoading) { <span class="spinner-border spinner-border-sm me-1"></span> }
                Filter
            </button>
        </div>
    </div>

    @if (errorMessage is not null)
    {
        <div class="alert alert-danger">@errorMessage</div>
    }

    @if (shipments is null)
    {
        <p class="text-muted">Loading shipments…</p>
    }
    else if (shipments.Count == 0)
    {
        <div class="alert alert-info">No shipments found.</div>
